// Runtime of a page generated by uxui-gen: reads fixtures, plays channel scripts, applies live
// effects and draws the sections into the skeleton index.html holds. Plain JS, no build step.
(function () {
  "use strict";
  const { page, channels, fixtures } = window.UXUI;
  const query = new URLSearchParams(location.search);
  const params = {};
  for (const name of page.params) params[name] = query.get(name);
  const commands = (window.UXUI_COMMANDS = []);

  // PART: expressions
  // The binding expressions the page uses: paths (params., row., state.), literals, ==, !=, not,
  // and, or, and matches(params). Text that is no expression is a literal.
  function lookup(path, scope) {
    let value = scope;
    for (const part of path.split(".")) {
      if (value === null || value === undefined) return undefined;
      value = value[part];
    }
    return value;
  }
  function term(text, scope) {
    text = text.trim();
    if (text === "matches(params)") return scope.matches ? scope.matches() : true;
    if (text === "true") return true;
    if (text === "false") return false;
    if (text === "null") return null;
    if (/^-?\d+(\.\d+)?$/.test(text)) return Number(text);
    if (/^(params|row|state|selection|draft|channel|actor)\./.test(text)) return lookup(text, scope);
    return text.replace(/^["']|["']$/g, "");
  }
  function evaluate(text, scope) {
    if (typeof text !== "string") return text;
    const or = text.split(/\s+or\s+/);
    if (or.length > 1) return or.some((part) => evaluate(part, scope));
    const and = text.split(/\s+and\s+/);
    if (and.length > 1) return and.every((part) => evaluate(part, scope));
    const trimmed = text.trim();
    if (trimmed.startsWith("not ")) return !evaluate(trimmed.slice(4), scope);
    const eq = trimmed.match(/^(.*?)\s*(==|!=)\s*(.*)$/);
    if (eq) {
      const same = String(term(eq[1], scope)) === String(term(eq[3], scope));
      return eq[2] === "==" ? same : !same;
    }
    return term(trimmed, scope);
  }
  // END PART

  // PART: fixture semantics
  // A read answered from fixtures: the view's rows (its `by_params` answer first), a derived
  // `by_id_from` view filtered by its key, and rows kept when they match the read's params (a
  // param the row does not hold, or that has no value, keeps it).
  function rowMatches(row, wanted) {
    return Object.entries(wanted).every(([name, value]) => {
      if (value === undefined || value === null || value === "" || !(name in row)) return true;
      return String(row[name]) === String(value);
    });
  }
  function readFixture(view, wanted) {
    const direct = fixtures.views[view];
    if (direct) return direct.rows.filter((row) => rowMatches(row, wanted));
    const derived = fixtures.derived[view];
    if (derived && derived.by_id_from) {
      const source = readFixture(derived.by_id_from, {});
      const id = wanted[derived.key] ?? wanted.id;
      return source.filter((row) => String(row[derived.key]) === String(id));
    }
    if (derived && derived.same_as) return readFixture(derived.same_as, wanted);
    return [];
  }
  // END PART

  // Section state: the read rows, the live events applied since, the status.
  const sections = page.sections.map((spec) => ({ spec, base: [], applied: [], rows: [], status: "loading", stale: false, pending: [], timer: null }));
  function readParams(section) {
    const out = {};
    for (const [name, expr] of Object.entries(section.spec.reads.params || {})) out[name] = evaluate(expr, { params });
    return out;
  }
  function load(section) {
    if (!section.spec.reads) return;
    section.base = readFixture(section.spec.reads.view, readParams(section)).map((row) => ({ ...row }));
    section.rows = section.applied.reduce((rows, event) => apply(section, rows, event), section.base.slice());
    section.status = section.rows.length ? "ready" : "empty";
    draw(section);
  }

  // PART: live and channel semantics
  // An effect on a section's rows. `insert_or_patch` patches the row whose `match` field equals
  // the payload's, else inserts it at the top; `insert_top` moves a held row to the top with the
  // payload's fields (one row per key, as ESS's renderers do from 0.98.1) and keeps `max_rows`.
  function apply(section, rows, event) {
    const live = section.spec.live;
    const key = live.match;
    const payload = event.payload || {};
    const at = rows.findIndex((row) => payload[key] !== undefined && row[key] === payload[key]);
    switch (live.effect) {
      case "insert_top": {
        const next = [{ ...(at < 0 ? {} : rows[at]), ...payload }, ...rows.filter((_, i) => i !== at)];
        return live.max_rows ? next.slice(0, live.max_rows) : next;
      }
      case "insert_or_patch":
        if (at < 0) return [{ ...payload }, ...rows];
        return rows.map((row, i) => (i === at ? { ...row, ...payload } : row));
      case "patch_row":
        return rows.map((row, i) => (i === at ? { ...row, ...payload } : row));
      case "remove_row":
        return rows.filter((_, i) => i !== at);
      case "replace":
        return [{ ...payload }];
      default:
        return rows;
    }
  }
  function deliver(channel, event) {
    for (const section of sections) {
      const live = section.spec.live;
      if (!live || live.channel !== channel) continue;
      if (live.on && !live.on.includes(event.event)) continue;
      if (live.only_if) {
        const wanted = readParams(section);
        const scope = { row: event.payload, params, matches: () => rowMatches(event.payload || {}, wanted) };
        if (!evaluate(live.only_if, scope)) continue;
      }
      section.pending.push(event);
      const flush = () => {
        section.timer = null;
        const events = section.pending;
        section.pending = [];
        if (live.effect === "refetch") return load(section);
        // The events applied so far are kept, so a refetch from fixtures keeps live rows.
        section.applied.push(...events);
        section.rows = events.reduce((rows, e) => apply(section, rows, e), section.rows);
        section.status = section.rows.length ? "ready" : "empty";
        draw(section);
      };
      if (live.coalesce) section.timer = section.timer || setTimeout(flush, live.coalesce);
      else flush();
    }
  }
  // The channel's lifecycle: live at start; a script beat moves it; `stale_after` after a
  // reconnect marks fed sections stale; back to live with `resume: refetch` re-reads them.
  const lifecycle = {};
  function setLifecycle(channel, state) {
    const before = lifecycle[channel];
    lifecycle[channel] = state;
    const spec = channels[channel] || {};
    clearTimeout(setLifecycle.timers?.[channel]);
    setLifecycle.timers = setLifecycle.timers || {};
    if (state === "reconnecting" && spec.stale_after) {
      setLifecycle.timers[channel] = setTimeout(() => lifecycle[channel] === "reconnecting" && setLifecycle(channel, "stale"), spec.stale_after);
    }
    for (const el of document.querySelectorAll(`.ui-live[data-channel="${channel}"]`)) {
      el.dataset.lifecycle = state;
      el.textContent = { connecting: "Connecting", live: "Live", reconnecting: "Reconnecting", stale: "Stale", closed: "Closed" }[state] || state;
    }
    for (const section of sections) {
      if (!section.spec.live || section.spec.live.channel !== channel) continue;
      section.stale = state === "stale" || state === "closed";
      if (state === "live" && (before === "reconnecting" || before === "stale") && spec.resume === "refetch") load(section);
      else draw(section);
    }
  }
  // A script plays each entry at its offset; a looping script restarts when its last entry has
  // played (the period of ESS's terminal renderer and test clock, and from ESS 0.98.1 of the
  // generated React app); a script whose last entry is at 0 s plays once.
  function play(channel) {
    const script = fixtures.scripts[channel];
    setLifecycle(channel, "live");
    if (!script || script.events.length === 0) return;
    const period = script.events[script.events.length - 1].at;
    const round = (start) => {
      for (const entry of script.events) {
        setTimeout(() => {
          if (entry.lifecycle) setLifecycle(channel, entry.lifecycle);
          else deliver(channel, { event: entry.event, payload: entry.payload });
        }, start + entry.at);
      }
      if (script.loop && period > 0) setTimeout(() => round(0), start + period);
    };
    round(0);
  }
  // END PART

  // Drawing.
  function el(tag, attrs, ...children) {
    const node = document.createElement(tag);
    for (const [name, value] of Object.entries(attrs || {})) {
      if (value === undefined || value === null || value === false) continue;
      if (name === "class") node.className = value;
      else if (name.startsWith("on")) node.addEventListener(name.slice(2), value);
      else node.setAttribute(name, value === true ? "" : value);
    }
    for (const child of children.flat()) if (child !== null && child !== undefined) node.append(child instanceof Node ? child : String(child));
    return node;
  }
  function format(value, as) {
    if (value === undefined || value === null) return "";
    if (as === "json" || (typeof value === "object" && as !== "list")) return el("code", {}, JSON.stringify(value));
    if (as === "list" && Array.isArray(value)) return value.map((v) => (typeof v === "object" ? JSON.stringify(v) : String(v))).join(", ");
    if (as === "timestamp") {
      const date = new Date(value);
      return isNaN(date) ? String(value) : date.toLocaleString(undefined, { timeZone: "UTC", dateStyle: "medium", timeStyle: "medium" });
    }
    if (typeof value === "number") return value.toLocaleString();
    return String(value);
  }
  function cell(field, row) {
    const value = row[field.field];
    if (field.as === "badge") {
      const tone = (field.tones && field.tones[String(value)]) || field.tone || "neutral";
      return el("span", { class: `ui-badge tone-${tone}` }, format(value));
    }
    if (field.as === "toggle") return el("input", { type: "checkbox", checked: Boolean(value), disabled: true });
    // A list of KPI readings, whatever `as` says: one `metric value` chip each (change C3).
    if (/^List<[\w.]*KpiReading>$/.test(field.type || "") && Array.isArray(value)) {
      return el("span", { class: "kpis" }, value.map((r) => el("span", { class: "ui-badge tone-neutral" }, `${r.metric_key} ${format(r.value)}`)));
    }
    return format(value, field.as);
  }
  function hrefFor(navigate, row) {
    const search = new URLSearchParams();
    for (const [name, expr] of Object.entries(navigate.params || {})) search.set(name, evaluate(expr, { params, row }) ?? "");
    return `${navigate.to}.html?${search}`;
  }
  function actionControl(action, row, path) {
    if (action.visible && !evaluate(action.visible, { params, row })) return null;
    if (action.navigate) return el("a", { class: "ui-button", href: hrefFor(action.navigate, row), "data-ui-path": path }, action.label);
    return el("button", { type: "button", class: "ui-button", "data-ui-path": path, onclick: () => run(action, row, path) }, action.label);
  }
  function run(action, row, path) {
    if (action.confirm && action.confirm.kind) return confirm(action, row, `${path}/confirm/overlay`);
    send(action, row);
  }
  function send(action, row) {
    if (!action.does) return;
    const input = {};
    for (const [name, expr] of Object.entries(action.bind || {})) input[name] = evaluate(expr, { params, row });
    commands.push({ command: action.does, input });
    document.getElementById("commands").append(el("li", {}, `${action.does} ${JSON.stringify(input)}`));
  }
  function confirm(action, row, path) {
    const host = document.getElementById("overlay");
    const close = () => host.replaceChildren();
    host.replaceChildren(
      el("div", { class: "backdrop" },
        el("div", { class: "dialog", role: "dialog", "aria-modal": "true", "data-ui-path": path },
          el("h2", {}, action.confirm.title || action.label),
          action.confirm.body ? el("p", {}, action.confirm.body) : null,
          el("div", { class: "dialog-actions" },
            el("button", { type: "button", class: "ui-button", onclick: close }, "Cancel"),
            el("button", { type: "button", class: "ui-button ui-emphasis-primary", onclick: () => { close(); send(action, row); } }, action.confirm.confirm_label)))));
  }
  function drawRecord(section) {
    const row = section.rows[0] || {};
    return el("dl", { class: "record" }, section.spec.fields.map((field) =>
      el("div", { "data-ui-path": field.path }, el("dt", {}, field.label), el("dd", {}, cell(field, row)))));
  }
  function drawCollection(section) {
    const { spec } = section;
    const head = el("tr", {}, spec.fields.map((f) => el("th", { "data-ui-path": f.path }, f.label)), spec.row_actions.length ? el("th", {}, "") : null);
    const body = sorted(section.rows, spec.sort).map((row) => {
      const rowPath = `${spec.path}/rows/${row[spec.reads.key]}`;
      return el("tr", { class: "row", "data-ui-path": rowPath },
        spec.fields.map((f) => el("td", { "data-ui-path": `${rowPath}/columns/${f.name}`, "data-column": f.name }, cell(f, row))),
        spec.row_actions.length ? el("td", { class: "row-actions" }, spec.row_actions.map((a) => actionControl(a, row, `${rowPath}/row_actions/${a.name}`))) : null);
    });
    return el("table", { class: "ui-table" }, el("thead", {}, head), el("tbody", {}, body));
  }
  function compare(a, b) {
    const [x, y] = [Number(a), Number(b)];
    return Number.isNaN(x) || Number.isNaN(y) ? String(a ?? "").localeCompare(String(b ?? "")) : x - y;
  }
  // A collection's `sort`: rows in the order of its field, also after live inserts.
  function sorted(rows, sort) {
    if (!sort || !sort.by) return rows;
    const dir = sort.dir === "desc" ? -1 : 1;
    return [...rows].sort((a, b) => dir * compare(a[sort.by], b[sort.by]));
  }
  function drawChart(section) {
    const { spec } = section;
    // Points in the order of their x value, also after live inserts (change C1).
    const rows = sorted(section.rows, { by: spec.x });
    const series = spec.series || [];
    const max = Math.max(1, ...rows.flatMap((row) => series.map((name) => Number(row[name]) || 0)));
    const step = rows.length > 1 ? 100 / (rows.length - 1) : 100;
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", "0 0 100 50");
    svg.setAttribute("preserveAspectRatio", "none");
    svg.setAttribute("class", "ui-chart-svg");
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", series.join(", ").replace(/_/g, " "));
    series.forEach((name, index) => {
      const line = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
      line.setAttribute("class", `ui-series ui-series-${index}`);
      line.setAttribute("fill", "none");
      line.setAttribute("points", rows.map((row, at) => `${at * step},${50 - ((Number(row[name]) || 0) / max) * 48}`).join(" "));
      svg.append(line);
    });
    const xs = el("div", { class: "chart-x" }, rows.map((row) => el("span", {}, format(row[spec.x]))));
    const legend = el("ul", { class: "legend" }, series.map((name, index) => el("li", {}, el("span", { class: `ui-swatch ui-series-${index}` }), name.replace(/_/g, " "))));
    return el("figure", { class: "chart" }, svg, xs, legend);
  }
  function draw(section) {
    const node = document.querySelector(`[data-ui-path="${section.spec.path}"]`);
    if (!node) return;
    node.dataset.status = section.stale ? "stale" : section.status;
    node.querySelector(".stale-badge").hidden = !section.stale;
    const body = node.querySelector(".body");
    if (section.status === "empty") return body.replaceChildren(el("p", { class: "muted" }, section.spec.empty));
    const drawn = { record: drawRecord, collection: drawCollection, chart: drawChart }[section.spec.component](section);
    body.replaceChildren(drawn);
  }

  // Header: switch links keep the params the target declares by name; actions run.
  for (const link of document.querySelectorAll(".switch a[data-page]")) link.href = `${link.dataset.page}.html?${new URLSearchParams(params)}`;
  for (const action of page.header.actions) {
    const button = document.querySelector(`[data-ui-path="${action.path}"]`);
    if (button) button.addEventListener("click", () => run(action, {}, action.path));
  }
  for (const section of sections) load(section);
  for (const channel of new Set(sections.filter((s) => s.spec.live).map((s) => s.spec.live.channel).concat(page.header.live || []))) play(channel);
})();
